 internal/ui/netdiag/view.go         |  9 ++++++++-
 internal/ui/theme/styles.go         | 10 ++++++++++
 9 files changed, 94 insertions(+), 17 deletions(-)
diff --git i/internal/ui/netdiag/header.go w/internal/ui/netdiag/header.go
index d9d265db..97aef36a 100644
--- i/internal/ui/netdiag/header.go
+++ w/internal/ui/netdiag/header.go
@@ -17,10 +17,12 @@ import (
 // GetTitle implements HeaderView
 func (m *Model) GetTitle() string {
 	base := theme.IconNetwork + " Network"
+	if m.activeTab == tabDiagnostics && m.state == StateTrace {
+		return m.traceTitle(base)
+	}
 	if m.state == StateDetails {
 		if label := m.selected.Title; label != "" {
-			detailStyle := lipgloss.NewStyle().Foreground(theme.ColorPrimary).Background(theme.ColorBackground)
-			return base + detailStyle.Render(" "+theme.IconChevronRight+" "+label)
+			return base + titleTrailStyle().Render(" "+theme.IconChevronRight+" "+label)
 		}
 	}
 	return base
@@ -107,9 +109,15 @@ func (m *Model) GetShortcuts() shortcut.Shortcuts {
 	}

 	switch m.state {
+	case StateTrace:
+		return m.traceShortcuts()
 	case StateInput:
+		enter := shortcut.Shortcut{Key: "enter", Description: "Run the checks"}
+		if m.focusedField == fieldTraceButton {
+			enter = shortcut.Shortcut{Key: "enter", Description: "Trace the path", Disabled: !m.traceable().Enabled()}
+		}
 		return append(tabShortcuts, shortcut.Shortcuts{
-			{Key: "enter", Description: "Run the checks"},
+			enter,
 			{Key: "?", Description: "Help"},
 		}...)
 	case StateRunning:
@@ -190,6 +198,9 @@ func (m *Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
 			Style: theme.HeaderValueStyle,
 		})
 	}
+	if m.state == StateTrace {
+		return append(info, m.pathModel.headerInfo()...)
+	}
 	if m.activeTab != tabDiagnostics || m.state == StateInput {
 		return info
 	}
@@ -289,6 +300,9 @@ func (m *Model) activeFooter() (*components.FooterMessage, components.Status) {
 	case tabPath:
 		return &m.pathModel.footer, m.pathModel.statusLine()
 	}
+	if m.state == StateTrace {
+		return &m.pathModel.footer, m.pathModel.statusLine()
+	}
 	return &m.footer, m.statusLine()
 }

@@ -300,6 +314,16 @@ func (m *Model) statusLine() components.Status {
 	if m.state == StateRunning {
 		return components.Status{Text: m.progressLabel(), Activity: true}
 	}
+	if m.state == StateInput {
+		if st := m.traceValidation.Status(); st.Text != "" {
+			return st
+		}
+	}
+	if m.state == StateInput {
+		if a := m.traceable(); !a.Enabled() {
+			return components.Status{Text: a.Reason, Level: components.LevelWarning}
+		}
+	}
 	return components.Status{}
 }

@@ -348,6 +372,8 @@ func (m *Model) GetHelpContent() help.Content {
 			{Key: "enter (Path)", Description: "Trace the path to the target typed in the field, or trace again once a trace is done (Path tab)"},
 			{Key: "esc (Path, running)", Description: "Cancel the trace and keep the hops already seen (Path tab)"},
 			{Key: "esc (Path, done)", Description: "Edit the target again, keeping its value (Path tab)"},
+			{Key: "enter (Trace Path button)", Description: "Trace the path to the form's target in a sub-level of the Diagnostics tab (Diagnostics tab)"},
+			{Key: "esc (trace)", Description: "Cancel a running trace; once it ended, go back to the form with its fields kept (Diagnostics tab)"},
 			{Key: "ctrl+o (Path)", Description: "Choose where the trace starts: this machine or a running container; ↑↓ to move, enter to choose, esc to close (Path tab)"},
 		},
 		Sections: []help.Section{
diff --git i/internal/ui/netdiag/model.go w/internal/ui/netdiag/model.go
index 9e0277b2..af0c0883 100644
--- i/internal/ui/netdiag/model.go
+++ w/internal/ui/netdiag/model.go
@@ -24,6 +24,7 @@ const (
 	StateRunning                  // The pipeline is walking its stages
 	StateResults                  // The checks and their verdicts
 	StateDetails                  // One check explained
+	StateTrace                    // The Path tab's trace, opened from the form's Trace Path button
 )

 // Tab indices. tabCount is what Tab cycles through, and it is a constant
@@ -47,11 +48,12 @@ const (
 // follow from the target and from what has already failed, so a question that
 // was never worth asking is no longer asked.
 const (
-	fieldTarget    = 0
-	fieldPort      = 1
-	fieldDNSServer = 2
-	fieldButton    = 3
-	fieldCount     = 4
+	fieldTarget      = 0
+	fieldPort        = 1
+	fieldDNSServer   = 2
+	fieldRunButton   = 3
+	fieldTraceButton = 4
+	fieldCount       = 5
 )

 // problemsToken filters the table down to what is not settled.
@@ -95,6 +97,11 @@ type Model struct {
 	dnsServerInput textinput.Model
 	focusedField   int

+	// traceValidation and traceMarks carry the Trace Path target's refusal:
+	// the footer line and the underline (Rule 140, DEVDESK-470).
+	traceValidation components.Validation
+	traceMarks      components.InvalidMarks
+
 	// Running state
 	runGen     int // incremented each run; results from a superseded run are dropped
 	runStage   netcheck.StageID
diff --git i/internal/ui/netdiag/run.go w/internal/ui/netdiag/run.go
index 216df883..fee2155a 100644
--- i/internal/ui/netdiag/run.go
+++ w/internal/ui/netdiag/run.go
@@ -18,6 +18,9 @@ func (m *Model) StartRun() (*Model, tea.Cmd) {
 		return m, m.footer.Error(capitalize(err.Error()))
 	}

+	m.traceValidation.Submit(nil)
+	m.syncTraceMarks()
+
 	m.runGen++
 	m.state = StateRunning
 	m.results = netcheck.Results{}
diff --git i/internal/ui/netdiag/update.go w/internal/ui/netdiag/update.go
index 08bbb647..42687828 100644
--- i/internal/ui/netdiag/update.go
+++ w/internal/ui/netdiag/update.go
@@ -277,6 +277,8 @@ func (m *Model) handleKey(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
 		return m.handleKeyResults(msg)
 	case StateDetails:
 		return m.handleKeyDetails(msg)
+	case StateTrace:
+		return m.handleKeyTrace(msg)
 	}
 	return m, nil
 }
@@ -304,9 +306,12 @@ func (m *Model) handleKeyInput(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
 		m.moveFocus(-1)
 		return m, nil
 	case "enter":
-		// enter runs from anywhere in the form: with three fields and one
-		// button there is nothing else it could mean, and making the user walk
-		// to the button first is a step that buys nothing.
+		// enter runs the checks from anywhere in the form, so the user need
+		// not walk to the button first; only the Trace Path button means
+		// something else.
+		if m.focusedField == fieldTraceButton {
+			return m.traceFromForm()
+		}
 		return m.StartRun()
 	case "esc":
 		return m, nil
@@ -341,6 +346,7 @@ func (m *Model) updateActiveInput(msg tea.Msg) (*Model, tea.Cmd) {
 	switch m.focusedField {
 	case fieldTarget:
 		m.targetInput, cmd = m.targetInput.Update(msg)
+		m.revalidateTrace()
 	case fieldPort:
 		m.portInput, cmd = m.portInput.Update(msg)
 	case fieldDNSServer:
diff --git i/internal/ui/netdiag/view.go w/internal/ui/netdiag/view.go
index a3614fae..5b2b576c 100644
--- i/internal/ui/netdiag/view.go
+++ w/internal/ui/netdiag/view.go
@@ -62,6 +62,8 @@ func (m *Model) Render() string {
 		return m.renderChecks()
 	case StateDetails:
 		return m.detailsViewport.View()
+	case StateTrace:
+		return m.pathModel.view()
 	}
 	return ""
 }
@@ -75,7 +77,12 @@ func (m *Model) renderInputForm() string {
 	b.WriteString("\n")
 	b.WriteString(m.renderTextInputField("DNS Server", m.dnsServerInput, fieldDNSServer))
 	b.WriteString("\n\n")
-	b.WriteString("  " + theme.RenderButton("Run Diagnostics", m.focusedField == fieldButton, "primary"))
+	traceVariant := "primary"
+	if !m.traceable().Enabled() {
+		traceVariant = "disabled"
