134	func (pm *PathModel) update(msg tea.Msg) (*PathModel, tea.Cmd) {
135		switch msg := msg.(type) {
136		case pathResolvedMsg:
137			return pm.handleResolved(msg)
138		case pathHopMsg:
139			return pm.handleHop(msg)
140		case pathDoneMsg:
141			return pm.handleDone(msg)
142		case pathSourcesMsg:
143			return pm.handleSources(msg)
144		case tea.KeyPressMsg:
145			return pm.handleKey(msg)
146		case tea.PasteMsg:
147			return pm.handlePaste(msg)
148		}
149		// Anything else is a footer expiry or the cursor blink of the field: the
150		// field needs the blink itself, or its cursor freezes.
151		pm.footer.Handle(msg)
152		var cmd tea.Cmd
153		pm.input, cmd = pm.input.Update(msg)
154		return pm, cmd
