161		pm.addr = msg.addr
162		pm.platform = msg.platform
163		route := newPathRoute(msg.route, msg.routeErr)
164		pm.route = &route
165		if !msg.source.isHost() {
166			c := newPathContainer(msg.source, msg.ctr, msg.ctrErr).withBridgeRead(msg.bridge)
167			pm.container = &c
168		}
169		pm.refreshSteps()
170		return pm, waitForPathMsg(pm.msgs)
171	}
