182	func (pm *PathModel) handleDone(msg pathDoneMsg) (*PathModel, tea.Cmd) {
183		if msg.gen != pm.gen {
184			return pm, nil
185		}
186		pm.releaseRun()
187		if msg.err != nil {
188			return pm.handleDoneError(msg.err)
189		}
190		res := msg.result
191		pm.result = &res
192		pm.hops = res.Hops
193		pm.refreshSteps()
194		pm.state = pathDone
195		return pm, nil
196	}
