198	// handleDoneError ends a failed run. A kernel "no route" keeps the local rows
199	// (source, container, interface, gateway) with the route marked NoRoute; any
200	// other error clears every row.
201	func (pm *PathModel) handleDoneError(err error) (*PathModel, tea.Cmd) {
202		pm.hops = nil
203		if nettrace.IsNoRoute(err) {
204			pm.route = &pathRoute{NoRoute: true}
205			pm.refreshSteps()
