208			pm.container = nil
209			pm.platform = wslenv.Info{}
210			pm.table.SetItems(nil)
211		}
212		pm.errText = pathErrorLabel(pm.target.Host, err)
213		pm.state = pathEditing
214		return pm, pm.input.Focus()
