264	func (pm *PathModel) handleKey(msg tea.KeyPressMsg) (*PathModel, tea.Cmd) {
265		key := msg.String()
266		if pm.pickerOpen() {
267			return pm.handlePickerKey(key)
268		}
269		if key == pathSourceKey {
270			return pm.openPicker()
271		}
272		if isPathNavKey(key) {
273			return pm, pm.table.Update(msg)
274		}
275		switch pm.state {
276		case pathEditing:
277			return pm.handleEditKey(msg)
278		case pathRunning:
279			if key == "esc" {
280				return pm.cancelRun()
281			}
282		case pathDone:
283			switch key {
284			case "enter":
285				return pm.launch(pm.target)
286			case "esc":
287				pm.state = pathEditing
288				return pm, pm.input.Focus()
289			}
290		}
291		return pm, nil
292	}
