294	func (pm *PathModel) handleEditKey(msg tea.KeyPressMsg) (*PathModel, tea.Cmd) {
295		switch msg.String() {
296		case "enter":
297			return pm.launchFromInput()
298		case "esc", "tab", "shift+tab":
299			return pm, nil
300		}
301		return pm.updateInput(msg)
302	}
