79	func tracePlainTitle(m *Model) string { return ansi.Strip(m.GetTitle()) }
80	
81	func TestTraceLevelStateIsAppended(t *testing.T) {
82		for _, s := range []ViewState{StateInput, StateRunning, StateResults, StateDetails} {
83			if s >= StateTrace {
84				t.Errorf("StateTrace (%d) must come after every existing state, found %d", StateTrace, s)
85			}
86		}
87	}
