89	func TestPathModelStartFromFormPrefillsThenLaunches(t *testing.T) {
90		pm, fe := newPM(t)
91		fe.resolveFn = func(context.Context, string) ([]netip.Addr, error) {
92			return []netip.Addr{netip.MustParseAddr("1.1.1.1")}, nil
93		}
94		pm.errText = "stale"
95		gen := pm.gen
96	
97		cmd := pm.startFromForm(pathTarget{Host: "one.one.one.one"})
98	
99		if !pm.running() || pm.gen != gen+1 {
100			t.Fatalf("running=%v gen %d->%d, want a launched run", pm.running(), gen, pm.gen)
101		}
102		if got := pm.input.Value(); got != "one.one.one.one" {
103			t.Errorf("field = %q, want the host prefilled", got)
104		}
105		if pm.target.Host != "one.one.one.one" || pm.errText != "" {
106			t.Errorf("target=%q errText=%q, want the new target and no stale error", pm.target.Host, pm.errText)
107		}
108		if cmd == nil {
