100	// statusLine is derived on every frame (Rule 128).
101	func (pm *PathModel) statusLine() components.Status {
102		if pm.errText != "" {
103			return components.Status{Text: pm.errText, Level: components.LevelError}
104		}
105		if pm.pickerOpen() {
106			return pm.pickerStatus()
107		}
108		if pm.state != pathRunning {
109			if a := pm.launchable(); !a.Enabled() {
110				// The platform cannot trace: say so up front, derived every frame.
111				return components.Status{Text: a.Reason, Level: components.LevelWarning}
112			}
113			return components.Status{}
114		}
115		host := pm.target.Host
116		n := pm.hopCount()
117		if !pm.addr.IsValid() && n == 0 {
118			return components.Status{Text: "Resolving " + host + "...", Activity: true}
119		}
120		where := host
121		if pm.addr.IsValid() && pm.addr.String() != host {
122			where += " (" + pm.addr.String() + ")"
123		}
124		noun := "hops"
125		if n == 1 {
126			noun = "hop"
127		}
128		return components.Status{
129			Text:     fmt.Sprintf("Tracing %s — %d %s answered", where, n, noun),
130			Activity: true,
131		}
132	}
